-- ============================================================
-- Agent Financial Registry — Supabase Schema
-- Run this in the Supabase SQL editor to set up the registry tables.
-- ============================================================

-- ── registry_agents ──────────────────────────────────────────
CREATE TABLE IF NOT EXISTS registry_agents (
  id                      uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  name                    text        NOT NULL UNIQUE,
  symbol                  text,
  ecosystem               text        NOT NULL,
  x_handle                text,
  website                 text,
  bankr_profile           text,
  token_address           text,
  verification_status     text        DEFAULT 'Candidate',
  financial_activity_score integer,
  treasury_health         text        DEFAULT 'Pending',
  partnership_fit_score   integer,
  outreach_status         text,
  last_checked            text,
  admin_notes             text,
  priority                integer     DEFAULT 50,
  pfp                     text,
  gitlawb_repo            text,
  evidence_sources        text[]      DEFAULT '{}',
  created_at              timestamptz DEFAULT now(),
  updated_at              timestamptz DEFAULT now()
);

-- ── registry_agent_wallets ────────────────────────────────────
CREATE TABLE IF NOT EXISTS registry_agent_wallets (
  id          uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  agent_name  text        NOT NULL REFERENCES registry_agents(name) ON DELETE CASCADE,
  address     text        NOT NULL,
  label       text        NOT NULL,
  notes       text,
  created_at  timestamptz DEFAULT now()
);

-- ── registry_pending_updates ──────────────────────────────────
CREATE TABLE IF NOT EXISTS registry_pending_updates (
  id              uuid        DEFAULT gen_random_uuid() PRIMARY KEY,
  created_at      timestamptz DEFAULT now(),
  agent_name      text        NOT NULL,
  update_type     text        NOT NULL,
  proposed_data   jsonb       NOT NULL,
  diff_summary    text,
  luca_notes      text,
  status          text        DEFAULT 'pending',
  reviewed_at     timestamptz,
  reviewer_notes  text
);

-- ── Indexes ───────────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_registry_agents_priority
  ON registry_agents (priority DESC);

CREATE INDEX IF NOT EXISTS idx_registry_agents_ecosystem
  ON registry_agents (ecosystem);

CREATE INDEX IF NOT EXISTS idx_registry_agent_wallets_agent_name
  ON registry_agent_wallets (agent_name);

CREATE INDEX IF NOT EXISTS idx_registry_pending_updates_status
  ON registry_pending_updates (status);

CREATE INDEX IF NOT EXISTS idx_registry_pending_updates_created
  ON registry_pending_updates (created_at DESC);

-- ── Auto-update updated_at trigger ───────────────────────────
CREATE OR REPLACE FUNCTION update_registry_agents_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_registry_agents_updated_at ON registry_agents;
CREATE TRIGGER trg_registry_agents_updated_at
  BEFORE UPDATE ON registry_agents
  FOR EACH ROW EXECUTE FUNCTION update_registry_agents_updated_at();


